package service

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"sort"
	"sync/atomic"
	"time"
)

// LiveRequest is an observation, never a billing record or an SLA denominator.
// Identifiers are generated by the gateway; no request bodies or credentials are stored.
type LiveRequest struct {
	ID                   string     `json:"id"`
	Version              int64      `json:"version"`
	UserID               int64      `json:"user_id"`
	APIKeyID             int64      `json:"api_key_id"`
	KeyName              string     `json:"key_name"`
	GroupName            string     `json:"group_name,omitempty"`
	AccountID            int64      `json:"account_id,omitempty"`
	Model                string     `json:"model"`
	Endpoint             string     `json:"endpoint"`
	RequestID            string     `json:"request_id"`
	RequestType          string     `json:"request_type"`
	Turn                 int        `json:"turn,omitempty"`
	Status               string     `json:"status"`
	StartedAt            time.Time  `json:"started_at"`
	UpdatedAt            time.Time  `json:"updated_at"`
	FinishedAt           *time.Time `json:"finished_at,omitempty"`
	ElapsedMs            int64      `json:"elapsed_ms"`
	DurationMs           *int64     `json:"duration_ms,omitempty"`
	InputTokens          *int       `json:"input_tokens,omitempty"`
	OutputTokens         *int       `json:"output_tokens,omitempty"`
	ImageOutputTokens    *int       `json:"image_output_tokens,omitempty"`
	AudioOutputTokens    *int       `json:"audio_output_tokens,omitempty"`
	FirstByteMs          *int       `json:"first_byte_ms,omitempty"`
	FirstTokenMs         *int       `json:"first_token_ms,omitempty"`
	FirstOutputKind      string     `json:"first_output_kind,omitempty"`
	Reason               string     `json:"reason,omitempty"`
	HTTPStatus           int        `json:"http_status,omitempty"`
	ActualCost           *float64   `json:"actual_cost,omitempty"`
	CacheReadTokens      *int       `json:"cache_read_tokens,omitempty"`
	CacheCreationTokens  *int       `json:"cache_creation_tokens,omitempty"`
	UserAgent            *string    `json:"user_agent,omitempty"`
	IPAddress            *string    `json:"ip_address,omitempty"`
	ReasoningEffort      *string    `json:"reasoning_effort,omitempty"`
	TimingVersion        int        `json:"timing_version"`
	NativeCompactionV2   bool       `json:"native_compaction_v2"`
	IsComplete           *bool      `json:"is_complete,omitempty"`
	LastTokenMs          *int       `json:"last_token_ms,omitempty"`
	FirstOutputMs        *int       `json:"first_output_ms,omitempty"`
	ImageCount           int        `json:"image_count,omitempty"`
	ImageSize            *string    `json:"image_size,omitempty"`
	VideoCount           int        `json:"video_count,omitempty"`
	VideoResolution      *string    `json:"video_resolution,omitempty"`
	VideoDurationSeconds *int       `json:"video_duration_seconds,omitempty"`
	BillingMode          *string    `json:"billing_mode,omitempty"`
}

type LiveRequestSnapshot struct {
	Items            []LiveRequest `json:"items"`
	ServerNow        time.Time     `json:"server_now"`
	WindowSeconds    int           `json:"window_seconds"`
	Limit            int           `json:"limit"`
	Truncated        bool          `json:"truncated"`
	PollAfterSeconds int           `json:"poll_after_seconds"`
}

// LiveRequestCache owns observation persistence; gateway services do not depend
// on a storage driver or expose its commands to handlers.
type LiveRequestCache interface {
	Store(ctx context.Context, id string, userID, version int64, updatedAt time.Time, data []byte) error
	List(ctx context.Context, userID int64, since time.Time) ([]string, bool, error)
	BindUsage(ctx context.Context, id string, data []byte) error
	UsageBindings(ctx context.Context, ids []string) ([]string, error)
}

type LiveRequestService struct {
	cache       LiveRequestCache
	writes      chan struct{}
	lastWarning atomic.Int64
	usage       LiveUsageReader
}

func NewLiveRequestService(cache LiveRequestCache) *LiveRequestService {
	return &LiveRequestService{cache: cache, writes: make(chan struct{}, 32)}
}

// Bound both queued work and write latency. Gateway observation is best effort;
// it must never change admission, forwarding or settlement decisions.
func (s *LiveRequestService) Publish(record LiveRequest) {
	if s == nil || s.cache == nil {
		return
	}
	// Copy pointer values on the caller's goroutine before a result can be reused.
	data, err := json.Marshal(record)
	if err != nil {
		s.warn("encoding")
		return
	}
	s.enqueue(func(ctx context.Context) error { return s.storeEncoded(ctx, record, data) })
}

func (s *LiveRequestService) warn(reason string) {
	now := time.Now().Unix()
	previous := s.lastWarning.Load()
	if now-previous >= 60 && s.lastWarning.CompareAndSwap(previous, now) {
		slog.Warn("live_request_observation_dropped", "reason", reason)
	}
}

func (s *LiveRequestService) store(ctx context.Context, record LiveRequest) error {
	data, err := json.Marshal(record)
	if err != nil {
		return err
	}
	return s.storeEncoded(ctx, record, data)
}

func (s *LiveRequestService) storeEncoded(ctx context.Context, record LiveRequest, data []byte) error {
	return s.cache.Store(ctx, record.ID, record.UserID, record.Version, record.UpdatedAt, data)
}

func (s *LiveRequestService) List(ctx context.Context, userID int64) (*LiveRequestSnapshot, error) {
	if s == nil || s.cache == nil {
		return nil, errors.New("live requests unavailable")
	}
	now := time.Now().UTC()
	values, truncated, err := s.cache.List(ctx, userID, now.Add(-5*time.Minute))
	if err != nil {
		return nil, err
	}
	result := &LiveRequestSnapshot{Items: []LiveRequest{}, ServerNow: now, WindowSeconds: 300, Limit: 200, Truncated: truncated, PollAfterSeconds: 2}
	if len(values) == 0 {
		result.PollAfterSeconds = 5
		return result, nil
	}
	for _, raw := range values {
		var record LiveRequest
		if json.Unmarshal([]byte(raw), &record) != nil || (userID > 0 && record.UserID != userID) {
			continue
		}
		if (record.Status == "processing" || record.Status == "transmitting") && now.Sub(record.UpdatedAt) > 45*time.Second {
			record.Status = "unknown"
		}
		if userID > 0 {
			record.AccountID = 0
		}
		result.Items = append(result.Items, record)
	}
	if err := s.enrich(ctx, result.Items); err != nil {
		return nil, err
	}
	sort.Slice(result.Items, func(i, j int) bool {
		if result.Items[i].StartedAt.Equal(result.Items[j].StartedAt) {
			return result.Items[i].ID > result.Items[j].ID
		}
		return result.Items[i].StartedAt.After(result.Items[j].StartedAt)
	})
	return result, nil
}
